import type { CalculatorSeoData } from './types';
// ---------------------------------------------------------------------------
// Inventory Planning Calculator (suite) — Phase 17: EOQ, reorder point and
// safety stock, carrying cost, turnover and cash conversion cycle. Figures are
// generated by the same functions the tabs run.
